-- Demo results for the local screenshot rig only (scripts/shots.sh). Never seeded anywhere else.
-- Marc (1001, the app's shots) and Léa (1002, the bib page) lose whatever an earlier pass
-- uploaded, and keep only the sample runs of `npm run seed:runs` (dated before the race window,
-- so they rank nowhere and their screens still show the race before the finish).
DELETE FROM runs WHERE entrant_id IN ('deauville-2026-1001', 'deauville-2026-1002') AND id NOT LIKE 'seed-%';
